package utils

import "strings"

var internalSQLMarkers = []string{
	"/* zentro:",
	"-- zentro:",
}

// IsInternalSQL reports whether a SQL statement was generated by Zentro for
// internal workflows and should stay hidden from user-facing telemetry surfaces.
func IsInternalSQL(sql string) bool {
	normalized := strings.ToLower(strings.TrimSpace(sql))
	if normalized == "" {
		return false
	}

	for _, marker := range internalSQLMarkers {
		if strings.Contains(normalized, marker) {
			return true
		}
	}

	return false
}
